def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'
    if n == 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_opp = opp[-1]
    last_me = me[-1]
    opp_def = opp.count('D')

    if n >= 10 and opp_def >= 5 and opp_def * 10 > n * 3:
        return 'D'

    if opp_def >= 5:
        if opp[-5:].count('D') >= 3:
            return 'D'

    if last_opp == 'D':
        if last_me == 'D':
            return 'C'
        if opp_def > 4:
            return 'D'
        return 'C'

    if last_me == 'D':
        if n >= 3 and opp[-3:].count('C') == 3:
            return 'D'
        return 'C'

    if opp_def > 0 and n >= 20 and opp[-20:].count('C') == 20:
        return 'D'

    return 'C'
